-- Secure private attachments for employee direct messages.
-- The bucket is private; object reads require a matching message and participant membership.
alter table public.direct_messages add column if not exists attachment_path text, add column if not exists attachment_name text, add column if not exists attachment_type text, add column if not exists attachment_size bigint;
alter table public.direct_messages drop constraint if exists direct_messages_body_check, drop constraint if exists direct_messages_attachment_metadata_check;
alter table public.direct_messages add constraint direct_messages_body_check check (char_length(body) <= 4000 and (char_length(body) > 0 or attachment_path is not null)), add constraint direct_messages_attachment_metadata_check check ((attachment_path is null and attachment_name is null and attachment_type is null and attachment_size is null) or (attachment_path is not null and attachment_name is not null and char_length(attachment_name) between 1 and 255 and attachment_type in ('image/jpeg','image/png','image/webp','image/gif','application/pdf','text/plain','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') and attachment_size between 1 and 10485760));
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('employee-message-attachments','employee-message-attachments',false,10485760,array['image/jpeg','image/png','image/webp','image/gif','application/pdf','text/plain','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict (id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Active employees upload message attachments" on storage.objects;
create policy "Active employees upload message attachments" on storage.objects for insert to authenticated with check (bucket_id='employee-message-attachments' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.employee_profiles p where p.id=auth.uid() and p.is_active=true) and exists(select 1 from public.employee_profiles p where p.id::text=(storage.foldername(name))[2] and p.is_active=true));
drop policy if exists "Message participants read attachments" on storage.objects;
create policy "Message participants read attachments" on storage.objects for select to authenticated using (bucket_id='employee-message-attachments' and exists(select 1 from public.direct_messages dm where dm.attachment_path=storage.objects.name and (dm.sender_id=auth.uid() or dm.recipient_id=auth.uid())));
drop policy if exists "Message sender deletes own orphan attachments" on storage.objects;
create policy "Message sender deletes own orphan attachments" on storage.objects for delete to authenticated using (bucket_id='employee-message-attachments' and (storage.foldername(name))[1]=auth.uid()::text and not exists(select 1 from public.direct_messages dm where dm.attachment_path=storage.objects.name));
drop policy if exists "Employees send direct messages" on public.direct_messages;
create policy "Employees send direct messages" on public.direct_messages for insert to authenticated with check (sender_id=auth.uid() and recipient_id<>auth.uid() and exists(select 1 from public.employee_profiles p where p.id=recipient_id and p.is_active=true) and exists(select 1 from public.employee_profiles p where p.id=sender_id and p.is_active=true) and (attachment_path is null or ((storage.foldername(attachment_path))[1]=sender_id::text and (storage.foldername(attachment_path))[2]=recipient_id::text and exists(select 1 from storage.objects o where o.bucket_id='employee-message-attachments' and o.name=attachment_path)));
grant select,insert on public.direct_messages to authenticated;
